'use strict';
const KEY='sentineldrift.workspace.v1';
const initial=()=>({schema:1,requests:0,flagged:0,drift:0,champion:'rf-001',previous:null,candidate:null,canary:false,canarySamples:0,models:[{id:'rf-001',family:'Random Forest',status:'Champion',f1:.942,fnr:.061}],events:[],predictions:[],runs:[],datasets:[],settings:{threshold:60,canary:10,cooldown:30,enabled:true},history:[18,24,21,29,27,35,31,30,38,34,42,39,46,40,44,47,43,52,48,50,46,54,51,57]});
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||state.schema!==1)state=initial()}catch{state=initial()}
let page='',period='24h',filter='',busy=false;let storageOK=true;
const $=id=>document.getElementById(id);const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{storageOK=false;toast('Browser storage is unavailable or full. Changes only last for this session.')}}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4500)}
function event(title,detail,type='info'){state.events.unshift({id:crypto.randomUUID(),title,detail,type,time:new Date().toISOString()});state.events=state.events.slice(0,200);save()}
const pages=[['overview','◈','Overview'],['predictions','⌁','URL analysis'],['monitoring','⌇','Drift monitoring'],['recovery','⟳','Recovery pipeline'],['models','▧','Model registry'],['data','▤','Data workspace'],['incidents','◷','Audit & incidents'],['settings','⚙','Settings']];
function pill(label,tone=''){return `<span class="pill ${tone}">${esc(label)}</span>`}
function head(kicker,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`}
function btn(text,action,primary=false,disabled=false){return `<button type="button" class="button ${primary?'primary':''}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`}
function panel(title,body,right='',sub=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<small>${sub}</small>`:''}</div>${right}</div>${body}</section>`}
function metric(label,value,sub,icon){return `<div class="card"><div class="card-label">${label}<span>${icon}</span></div><div class="card-value">${value}</div><div class="card-sub">${sub}</div></div>`}
function chart(){let vals=state.history.slice(period==='1h'?-12:period==='7d'?-24:-20);const points=vals.map((v,i)=>`${45+i*(625/(vals.length-1))},${175-v*1.8}`).join(' ');return `<svg class="chart" viewBox="0 0 700 215" role="img" aria-label="Simulated traffic history"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5cdbb0" stop-opacity=".18"/><stop offset="1" stop-color="#5cdbb0" stop-opacity="0"/></linearGradient></defs>${[35,80,125,170].map((y,i)=>`<line x1="45" x2="675" y1="${y}" y2="${y}"/><text x="10" y="${y+4}">${80-i*20}</text>`).join('')}<polygon points="45,180 ${points} 670,180" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#5cdbb0" stroke-width="2"/>${vals.filter((_,i)=>i%3===0).map((v,i)=>`<text x="${45+i*(625/Math.ceil(vals.length/3))}" y="205">${String(i*3).padStart(2,'0')}:00</text>`).join('')}</svg><div class="legend"><span>Demo traffic / interval</span><span>Selected window: ${period}</span></div>`}
function loop(){const active=state.candidate?4:state.drift>.25?2:1;return `<div class="loop">${['Monitor','Detect','Diagnose','Recover','Validate','Deploy'].map((x,i)=>`${i?'<span class="loop-arrow">→</span>':''}<div class="loop-item ${i>active?'pending':''}"><div class="loop-icon">${['⌁','◎','⋈','⟳','✓','↗'][i]}</div>${x}</div>`).join('')}</div>`}
function activity(limit=5){return state.events.length?state.events.slice(0,limit).map(e=>`<div class="activity"><span class="activity-icon">${e.type==='error'?'!':'✓'}</span><div><p>${esc(e.title)}</p><small>${esc(e.detail)}</small></div><time>${new Date(e.time).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</time></div>`).join(''):'<div class="empty">No activity yet. Run a traffic scenario to start the loop.</div>'}
function overview(){return head('CONTROL CENTER','Your models. Always adapting.','Monitor threats, diagnose drift, and recover with confidence.',btn('↗ Export report','export')+btn('＋ Generate demo traffic','traffic',true))+`<div class="metrics">${metric('Analyzed URLs',state.requests.toLocaleString(),'This browser session workspace','↗')}${metric('Flagged by demo rules',state.flagged.toLocaleString(),'Rule score exceeds your threshold','◇')}${metric('Distribution shift',state.drift.toFixed(3),state.drift>.25?'<span class="amber">● Recovery recommended</span>':'<span class="green">● Within demo policy</span>','⌇')}${metric('Champion model',esc(state.champion),'Simulated registry · not serving ML','▧')}</div><div class="grid">${panel('Traffic overview',`<div class="panel-body">${chart()}</div>`,`<div class="tabs">${['1h','24h','7d'].map(t=>`<button data-period="${t}" class="${period===t?'active':''}">${t}</button>`).join('')}</div>`,'Illustrative history + generated scenario traffic')}${panel('Self-healing control loop',`<div class="panel-body">${loop()}<div class="summary-row"><span>Active policy</span><strong>${state.settings.enabled?'Enabled':'Paused'}</strong></div><div class="summary-row"><span>Candidate status</span><strong>${state.candidate?state.canary?'Canary running':'Awaiting deployment':'No candidate'}</strong></div><div class="statusline"><span>Governed recovery</span><a class="green" href="#recovery">Open pipeline →</a></div></div>`,pill('SIMULATION','blue'))}</div><div class="grid">${panel('Recent activity',`<div class="panel-body">${activity()}</div>`,'<a class="text-button" href="#incidents">View audit trail →</a>')}${panel('Deployment health',`<div class="panel-body"><div class="summary-row"><span>Workspace persistence</span><strong class="green">${storageOK?'Browser local storage':'Session only'}</strong></div><div class="summary-row"><span>Inference backend</span>${pill('Not connected','amber')}</div><div class="summary-row"><span>Telemetry source</span><strong>Demo scenarios</strong></div><div class="summary-row"><span>Canary allocation</span><strong>${state.canary?state.settings.canary:0}% simulated</strong></div><div class="mini-progress"><span style="width:${state.canary?state.settings.canary:0}%"></span></div><p class="help">Recovery and deployment actions update this workspace. No external infrastructure is changed.</p></div>`)}</div>`}
function predictions(){return head('INFERENCE WORKSPACE','Inspect a URL. Understand the signals.','Analyze lexical risk signals without opening or fetching the submitted URLs.')+`<div class="grid">${panel('URL analyzer',`<div class="panel-body"><form id="analyze-form"><div class="field"><label for="urls">URLs to analyze · one per line, up to 50</label><textarea id="urls" required placeholder="https://example.com\nhttps://account-verify.example.xyz/login"></textarea><div class="help">HTTP and HTTPS only. These are heuristic risk scores, not calibrated probabilities.</div></div><div class="actions"><button class="button primary" type="submit">⌁ Analyze URLs</button>${btn('Load sample URLs','samples')}</div><div id="analysis-error" class="error" role="alert"></div></form><div id="results" aria-live="polite"></div></div>`)}${panel('How the demo score works',`<div class="panel-body"><h3>Transparent, reproducible signals</h3><p>Each URL starts at 5 points. Additional signals are summed and capped at 99.</p><div class="summary-row"><span>Suspicious TLD</span><strong>+30</strong></div><div class="summary-row"><span>Credential-related keywords</span><strong>+25</strong></div><div class="summary-row"><span>IPv4 address as host</span><strong>+25</strong></div><div class="summary-row"><span>Encoded characters</span><strong>+15</strong></div><div class="summary-row"><span>Deep subdomains / long URL</span><strong>+15 / +10</strong></div><div class="summary-row"><span>HTTP / userinfo / punycode</span><strong>+10 / +25 / +20</strong></div><p class="help">A URL scoring below ${state.settings.threshold} is labeled lower risk, not safe. A trained classifier and calibrated confidence will replace this demo scorer.</p></div>`,pill('RULE-BASED','amber'))}</div>${panel('Analysis history',predictionTable(),btn('Download CSV','prediction-export'))}`}
function predictionTable(){return state.predictions.length?`<div class="table-wrap"><table><thead><tr><th>URL</th><th>RISK SCORE</th><th>ASSESSMENT</th><th>TIME</th></tr></thead><tbody>${state.predictions.slice(0,30).map(x=>`<tr><td class="mono">${esc(x.url)}</td><td>${x.score}/100</td><td>${pill(x.flag?'Elevated risk':'Lower risk',x.flag?'red':'')}</td><td class="mono">${new Date(x.time).toLocaleTimeString()}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Your URL analyses will appear here.</div>'}
function monitoring(){const rows=[['URL length',state.drift*1.3],['Subdomain depth',state.drift*.9],['Suspicious TLD',state.drift*1.6],['Encoding frequency',state.drift*.7],['HTTPS ratio',state.drift*.6]];return head('OBSERVABILITY','Catch the shift. Before it spreads.','Explore controlled distribution shifts and the resulting recovery decisions.',btn('Generate normal traffic','traffic')+btn('⚡ Inject attack wave','attack',true))+`<div class="metrics">${metric('Aggregate demo PSI',state.drift.toFixed(3),'Scenario-derived, not a statistical estimate','⌇')}${metric('High-shift features',rows.filter(r=>r[1]>.25).length,'Demo threshold: PSI > 0.25','◎')}${metric('Observed labels','Unavailable','No real labeled feedback connected','◇')}${metric('Monitor state',state.settings.enabled?'Enabled':'Paused','Policy controlled in settings','◉')}</div><div class="grid">${panel('Feature shift breakdown',`<div class="table-wrap"><table><thead><tr><th>FEATURE</th><th>DEMO PSI</th><th>STATUS</th></tr></thead><tbody>${rows.map(([n,v])=>`<tr><td>${n}</td><td class="mono">${v.toFixed(3)}</td><td>${pill(v>.25?'High shift':v>.1?'Moderate':'Stable',v>.25?'red':v>.1?'amber':'')}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Diagnostic assessment',`<div class="panel-body"><h3>${state.drift>.25?'Distribution shift detected':'Distribution within demo bounds'}</h3><p>${state.drift>.25?'The injected scenario changes URL characteristics. Feature shift alone does not establish concept drift or model degradation.':'No high-shift scenario is active. Generate traffic or inject an attack wave to test the recovery workflow.'}</p><div class="gate"><span>Performance degradation</span>${pill('Not measured','amber')}</div><div class="gate"><span>Recommended action</span><strong>${state.drift>.25?'Evaluate candidate':'Continue monitoring'}</strong></div><br><a href="#recovery" class="button primary">Inspect recovery pipeline →</a></div>`)}</div>`}
function recovery(){const r=state.runs[0];return head('AUTONOMOUS OPERATIONS','Recover deliberately. Deploy safely.','Exercise the recovery state machine and inspect every decision.',btn('Run failure scenario','fail',false,busy||!state.settings.enabled||state.canary)+btn('⟳ Run recovery','recover',true,busy||!state.settings.enabled||state.canary))+panel('Recovery pipeline',`<div class="panel-body">${loop()}<p class="help">Runs are deterministic simulations. No training takes place. Cooldown: ${state.settings.cooldown} minutes (enforced between successful candidate runs).</p><div class="steps">${[['01','Diagnose','Inspect the shift signal. Choose no action when no recovery is needed.'],['02','Adapt','Simulate a threshold adjustment or a full retraining candidate.'],['03','Validate','Check independent historical regression, adaptation, and false-negative limits.']].map(x=>`<div class="step"><b>${x[0]}</b><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div><br><div id="pipeline-log" class="log" aria-live="polite">${r?esc(r.log.join('\n')):'$ Waiting for a recovery scenario.\n$ Inject an attack wave in Drift monitoring to begin.'}</div></div>`,pill(busy?'RUNNING':r?r.status:'IDLE',busy?'amber':'blue'))+`<div class="grid equal">${panel('Candidate safety gates',`<div class="panel-body">${r&&r.gates?r.gates.map(g=>`<div class="gate"><div><h3>${esc(g.name)}</h3><p>${esc(g.detail)}</p></div>${pill(g.pass?'Pass':'Rejected',g.pass?'':'red')}</div>`).join(''):'<div class="empty">A candidate evaluation will populate these gates.</div>'}</div>`,'', 'Simulated holdout results; not empirical validation')}${panel('Deployment controls',`<div class="panel-body"><div class="summary-row"><span>Candidate</span><strong>${state.candidate?esc(state.candidate):'None'}</strong></div><div class="summary-row"><span>Canary state</span><strong>${state.canary?'Running':'Inactive'}</strong></div><div class="summary-row"><span>Demo canary observations</span><strong>${state.canarySamples} / 100 minimum</strong></div><div class="actions">${btn('Start canary','canary',true,!state.candidate||state.canary||busy)}${btn('Observe 100 requests','observe',false,!state.canary)}${btn('Promote candidate','promote',false,!state.canary||state.canarySamples<100)}${btn('Rollback','rollback',false,!state.canary&&!state.previous)}</div><p class="help">Promotion requires a passed candidate and 100 simulated observations. Rollback restores the previous champion or cancels a running canary.</p></div>`)}</div>${panel('Run history',runTable())}`}
function runTable(){return state.runs.length?`<div class="table-wrap"><table><thead><tr><th>RUN</th><th>STRATEGY</th><th>RESULT</th><th>STARTED</th></tr></thead><tbody>${state.runs.map(r=>`<tr><td class="mono">${r.id}</td><td>${r.strategy}</td><td>${pill(r.status,r.status==='Rejected'?'red':'blue')}</td><td>${new Date(r.time).toLocaleString()}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No recovery runs yet.</div>'}
function models(){return head('MODEL GOVERNANCE','Every version has a story.','Inspect model lifecycle changes and retain a reversible deployment history.',btn('Export registry','export'))+panel('Registered models',`<div class="table-wrap"><table><thead><tr><th>VERSION</th><th>FAMILY</th><th>STATE</th><th>DEMO F1</th><th>DEMO FNR</th><th>DETAILS</th></tr></thead><tbody>${state.models.map(m=>`<tr><td><strong class="mono">${esc(m.id)}</strong></td><td>${esc(m.family)}</td><td>${pill(m.status,m.status==='Rejected'?'red':m.status==='Champion'?'':'blue')}</td><td class="mono">${m.f1.toFixed(3)}</td><td class="mono">${(m.fnr*100).toFixed(1)}%</td><td><button class="text-button" data-model="${esc(m.id)}">Inspect ↗</button></td></tr>`).join('')}</tbody></table></div>`,'', 'All model versions and metrics in this workspace are illustrative.')+panel('Promotion contract',`<div class="panel-body"><div class="steps"><div class="step"><b>01 / LINEAGE</b><h3>Traceable candidates</h3><p>Every new demo candidate links to its recovery run and gate results.</p></div><div class="step"><b>02 / EVIDENCE</b><h3>Validation before deployment</h3><p>Rejected versions cannot enter canary. Promotion requires observations.</p></div><div class="step"><b>03 / REVERSIBILITY</b><h3>Keep the last champion</h3><p>Rollback restores both champion identity and model registry state.</p></div></div></div>`)}
function data(){return head('DATA OPERATIONS','Trust begins with the data.','Validate a labeled URL dataset and inspect its quality before future training.')+`<div class="grid equal">${panel('Validate dataset',`<div class="panel-body"><form id="dataset-form"><div class="field"><label for="dataset-name">Dataset name</label><input id="dataset-name" required maxlength="70" placeholder="url-feedback-batch-001"></div><div class="field"><label for="dataset-file">CSV file · up to 2 MB</label><input type="file" id="dataset-file" accept=".csv,text/csv" required><div class="help">Required headers: url,label. Labels must be 0 or 1. Quoted CSV fields are supported. Files are processed locally; only the quality summary is saved.</div></div><button class="button primary" type="submit">Validate CSV</button><div class="error" id="data-error" role="alert"></div></form><div id="data-result" aria-live="polite"></div></div>`)}${panel('Data contract',`<div class="panel-body"><div class="gate"><span>Required schema</span><strong class="mono">url, label</strong></div><div class="gate"><span>Allowed protocols</span><strong>HTTP / HTTPS</strong></div><div class="gate"><span>Duplicate URLs</span><strong>Rejected</strong></div><div class="gate"><span>Missing or invalid labels</span><strong>Rejected</strong></div><p class="help">Passing this contract does not establish provenance, label reliability, or train/test independence. Those checks belong in the real data pipeline.</p><br>${btn('Download example CSV','sample-csv')}</div>`)}</div>${panel('Dataset validation history',state.datasets.length?`<div class="table-wrap"><table><thead><tr><th>DATASET</th><th>ROWS</th><th>MALICIOUS</th><th>ISSUES</th><th>STATUS</th></tr></thead><tbody>${state.datasets.map(d=>`<tr><td>${esc(d.name)}</td><td>${d.rows}</td><td>${d.malicious}</td><td>${d.errors}</td><td>${pill(d.errors?'Rejected':'Passed',d.errors?'red':'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Upload a CSV to create your first validation report.</div>')}`}
function incidents(){const list=state.events.filter(e=>`${e.title} ${e.detail} ${e.type}`.toLowerCase().includes(filter.toLowerCase()));return head('TRACEABILITY','A record of every decision.','Search operational events, inspect incidents, and export your workspace history.',btn('Download audit JSON','audit-export'))+panel('Audit trail',list.length?`<div class="table-wrap"><table><thead><tr><th>EVENT</th><th>DETAIL</th><th>TYPE</th><th>TIME</th></tr></thead><tbody>${list.map(e=>`<tr><td><strong>${esc(e.title)}</strong></td><td>${esc(e.detail)}</td><td>${pill(e.type,e.type==='error'?'red':'blue')}</td><td class="mono">${new Date(e.time).toLocaleString()}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No matching events. Generate traffic or run a recovery scenario.</div>',`<input id="audit-search" class="filter" aria-label="Search audit events" placeholder="Search events…" value="${esc(filter)}">`)}
function settings(){return head('WORKSPACE CONFIGURATION','Your guardrails. Explicitly defined.','Changes apply to the demo workspace and persist in this browser.')+panel('Recovery policy',`<form id="settings-form" class="panel-body"><div class="setting-row"><div><h3>Recovery policy enabled</h3><p>Allow new recovery runs. Existing canary actions remain available.</p></div><input id="policy-enabled" type="checkbox" aria-label="Recovery policy enabled" ${state.settings.enabled?'checked':''}></div><div class="setting-row"><div><h3>Demo risk threshold</h3><p>Flag URLs when the lexical score reaches this threshold (1–99).</p></div><input id="risk-threshold" aria-label="Risk threshold" type="number" min="1" max="99" value="${state.settings.threshold}" required></div><div class="setting-row"><div><h3>Canary traffic allocation</h3><p>Simulated traffic percentage assigned to the candidate (1–50%).</p></div><input id="canary-weight" aria-label="Canary traffic percentage" type="number" min="1" max="50" value="${state.settings.canary}" required></div><div class="setting-row"><div><h3>Recovery cooldown</h3><p>Minutes between successful candidate runs (0–1440).</p></div><input id="cooldown" aria-label="Recovery cooldown minutes" type="number" min="0" max="1440" value="${state.settings.cooldown}" required></div><br><button class="button primary" type="submit">Save policy</button></form>`)+panel('Workspace data',`<div class="panel-body"><p>Download a snapshot before clearing this browser's demonstration history. Clearing does not affect GitHub or external systems.</p><br><div class="actions">${btn('Download workspace','export')}<button class="button danger" data-action="reset">Reset demo workspace</button></div></div>`)}
const renders={overview,predictions,monitoring,recovery,models,data,incidents,settings};
function render(){page=location.hash.slice(1)||'overview';if(!renders[page]){location.hash='overview';return}const meta=pages.find(x=>x[0]===page);$('breadcrumb').textContent=meta[2];$('navigation').innerHTML=pages.map(([id,icon,name])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><b>${icon}</b>${name}${id==='recovery'&&state.candidate?'<em>1</em>':''}</a>`).join('');$('main').innerHTML=renders[page]();document.title=`${meta[2]} · SentinelDrift`;bind()}
function showDialog(title,body){$('dialog-content').innerHTML=`<h2>${title}</h2>${body}`;$('dialog').showModal()}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Download prepared')}
function csv(v){return '"'+String(v).replaceAll('"','""')+'"'}
function scoreURL(raw){const u=new URL(raw);if(!['http:','https:'].includes(u.protocol)||!u.hostname)throw Error('Use a complete HTTP or HTTPS URL.');let score=5;const signals=[];const add=(condition,points,label)=>{if(condition){score+=points;signals.push(`${label} (+${points})`)}};add(/\.(xyz|top|club|work|gq|tk|bid|site)$/i.test(u.hostname),30,'Suspicious TLD');add(/login|verify|bank|account|password|credential/i.test(u.pathname+u.search+u.hostname),25,'Credential-related keyword');add(/^\d+\.\d+\.\d+\.\d+$/.test(u.hostname),25,'IPv4 host');add(/%[a-f\d]{2}/i.test(raw),15,'Encoded characters');add(u.hostname.split('.').length>4,15,'Deep subdomains');add(raw.length>100,10,'Long URL');add(u.protocol==='http:',10,'Unencrypted protocol');add(!!u.username,25,'User information in URL');add(u.hostname.includes('xn--'),20,'Internationalized hostname');return {url:raw,score:Math.min(score,99),signals,flag:Math.min(score,99)>=state.settings.threshold,time:new Date().toISOString()}}
function traffic(attack=false){state.requests+=100;state.flagged+=attack?74:8;state.drift=attack?.38:Math.max(.03,state.drift*.65);state.history.push(attack?83:44);state.history=state.history.slice(-30);event(attack?'Attack wave injected':'Normal traffic generated',`100 simulated requests · ${attack?'74':'8'} demo flags`,attack?'warning':'info');render();toast(attack?'Attack scenario active. Inspect the recovery pipeline.':'100 simulated requests recorded')}
async function recover(fail=false){if(busy||!state.settings.enabled||state.canary)return;const last=state.runs.find(r=>r.status==='Passed');if(!fail&&last&&Date.now()-Date.parse(last.time)<state.settings.cooldown*60000){toast('Recovery cooldown active. Change the cooldown in Settings to run again.');return}if(state.candidate){toast('Deploy or dismiss the existing candidate through canary / rollback first.');return}busy=true;const r={id:`run-${String(state.runs.length+1).padStart(3,'0')}`,time:new Date().toISOString(),strategy:state.drift>.25?'Full retraining':state.drift>.1?'Threshold recalibration':'No action',status:'Running',log:['[monitor] Reading demo distribution signal…']};state.runs.unshift(r);render();for(const line of ['[diagnose] '+(fail?'Failure scenario requested.':`PSI=${state.drift.toFixed(3)}; strategy=${r.strategy}`),'[recover] '+(r.strategy==='No action'&&!fail?'No recovery required.':'Simulating candidate evaluation; no ML training performed.')]){await new Promise(resolve=>setTimeout(resolve,500));r.log.push(line);if(page==='recovery')$('pipeline-log').textContent=r.log.join('\n')}
if(r.strategy==='No action'&&!fail){r.status='No action';r.log.push('[complete] Stable distribution. Champion preserved.');event('Recovery skipped','Stable demo distribution; no model update required.')}else{r.gates=[{name:'Historical regression',detail:fail?'F1 drop: 0.08 > allowed 0.02':'F1 drop: 0.004 ≤ allowed 0.02',pass:!fail},{name:'Recent adaptation',detail:'Demo F1 gain: +0.04',pass:true},{name:'Holdout false negatives',detail:fail?'Demo FNR: 0.09 > limit 0.05':'Demo FNR: 0.035 ≤ limit 0.05',pass:!fail}];const id=`${r.strategy==='Threshold recalibration'?'cal':'rf'}-${String(state.models.length+1).padStart(3,'0')}`;state.models.unshift({id,family:r.strategy==='Threshold recalibration'?'Recalibrated RF':'Random Forest',status:fail?'Rejected':'Candidate',f1:fail?.86:.96,fnr:fail?.09:.035,run:r.id});r.status=fail?'Rejected':'Passed';r.log.push(fail?'[gate] REJECTED. Champion unchanged.':'[gate] PASSED. Candidate ready for canary.');if(!fail)state.candidate=id;event(fail?'Candidate rejected':'Candidate passed safety gates',`${id} · ${r.id} · simulated evaluation`,fail?'error':'info')}busy=false;save();render();toast('Recovery scenario completed')}
function action(name){if(name==='traffic')traffic();else if(name==='attack')traffic(true);else if(name==='recover'||name==='fail')recover(name==='fail');else if(name==='samples')$('urls').value='https://example.com/docs\nhttp://account-verify.example.xyz/login\nhttps://portal.example.com/about';else if(name==='export')download('sentineldrift-workspace.json',JSON.stringify({...state,environment:'simulation',exportedAt:new Date().toISOString()},null,2));else if(name==='audit-export')download('sentineldrift-audit.json',JSON.stringify(state.events,null,2));else if(name==='prediction-export')download('url-analysis.csv','url,score,assessment,time\n'+state.predictions.map(p=>[p.url,p.score,p.flag?'elevated risk':'lower risk',p.time].map(csv).join(',')).join('\n'),'text/csv');else if(name==='sample-csv')download('example-urls.csv','url,label\nhttps://example.com,0\nhttp://account-verify.example.xyz/login,1\n','text/csv');else if(name==='canary'&&state.candidate&&!state.canary){state.canary=true;state.canarySamples=0;state.models.find(m=>m.id===state.candidate).status='Canary';event('Canary started',`${state.candidate} · ${state.settings.canary}% simulated allocation`);render()}else if(name==='observe'&&state.canary){state.canarySamples+=100;event('Canary observation completed','100 simulated observations; demo health checks passed.');render()}else if(name==='promote'&&state.canary&&state.canarySamples>=100){state.previous=state.champion;state.models.find(m=>m.id===state.champion).status='Archived';state.champion=state.candidate;state.models.find(m=>m.id===state.champion).status='Champion';state.candidate=null;state.canary=false;state.canarySamples=0;state.drift=.045;event('Candidate promoted',`${state.champion} is now the simulated champion`);render();toast('Champion updated. Rollback is available.')}else if(name==='rollback'){if(state.canary){state.models.find(m=>m.id===state.candidate).status='Rolled back';state.candidate=null;state.canary=false;state.canarySamples=0;event('Canary rolled back','Candidate removed; champion unchanged.','warning')}else if(state.previous){state.models.find(m=>m.id===state.champion).status='Rolled back';state.champion=state.previous;state.previous=null;state.models.find(m=>m.id===state.champion).status='Champion';event('Champion restored',`${state.champion} restored from previous version`,'warning')}render();toast('Rollback completed')}else if(name==='reset'){showDialog('Reset demonstration workspace?',`<p>This clears all local predictions, runs, datasets, and settings. Download a workspace snapshot first if you need to retain them.</p><button id="confirm-reset" class="button danger">Reset workspace</button><br><br>`);$('confirm-reset').onclick=()=>{if(busy){toast('Wait for the active recovery to complete.');return}state=initial();save();$('dialog').close();render();toast('Workspace reset')}}}
function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else if(quote||!cell)quote=!quote;else throw Error('Unexpected quote in CSV field.')}else if(!quote&&(c===','||c==='\n')){row.push(cell.replace(/\r$/,''));cell='';if(c==='\n'){if(row.some(x=>x.trim()))rows.push(row);row=[]}}else cell+=c}if(quote)throw Error('Unclosed quoted CSV field.');row.push(cell.replace(/\r$/,''));if(row.some(x=>x.trim()))rows.push(row);return rows}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;render()});document.querySelectorAll('[data-model]').forEach(b=>b.onclick=()=>{const m=state.models.find(m=>m.id===b.dataset.model);showDialog('Model version · '+esc(m.id),`<p>Family: ${esc(m.family)}<br>Status: ${esc(m.status)}<br>Recovery run: ${esc(m.run||'Initial demo seed')}<br>Source: deterministic demonstration fixture<br>Artifact: no trained model binary registered</p>`)});if($('audit-search'))$('audit-search').oninput=e=>{filter=e.target.value;const pos=e.target.selectionStart;render();$('audit-search').focus();$('audit-search').setSelectionRange(pos,pos)};
if($('analyze-form'))$('analyze-form').onsubmit=e=>{e.preventDefault();const rows=$('urls').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);$('analysis-error').textContent='';try{if(!rows.length||rows.length>50)throw Error('Enter between 1 and 50 URLs.');if(rows.some(x=>x.length>4096))throw Error('Each URL must be at most 4096 characters.');const results=rows.map((raw,i)=>{try{return scoreURL(raw)}catch{throw Error(`Line ${i+1}: enter a valid HTTP or HTTPS URL.`)}});state.requests+=results.length;state.flagged+=results.filter(x=>x.flag).length;state.predictions=[...results,...state.predictions].slice(0,500);event('URL batch analyzed',`${results.length} URLs analyzed using local lexical rules`);render();$('results').innerHTML=results.map(r=>`<div class="result">${pill(r.flag?'Elevated risk':'Lower risk',r.flag?'red':'')}<h3>${r.score}/100 · lexical risk</h3><p class="mono">${esc(r.url)}</p><ul>${r.signals.length?r.signals.map(s=>`<li>${esc(s)}</li>`).join(''):'<li>No additional demo signals; base score 5.</li>'}</ul><p>Heuristic assessment only. This does not establish whether a URL is malicious.</p></div>`).join('')}catch(err){$('analysis-error').textContent=err.message}};
if($('settings-form'))$('settings-form').onsubmit=e=>{e.preventDefault();const threshold=Number($('risk-threshold').value),canary=Number($('canary-weight').value),cooldown=Number($('cooldown').value);if(!Number.isInteger(threshold)||threshold<1||threshold>99||!Number.isInteger(canary)||canary<1||canary>50||!Number.isInteger(cooldown)||cooldown<0||cooldown>1440){toast('Enter valid whole-number settings.');return}state.settings={enabled:$('policy-enabled').checked,threshold,canary,cooldown};event('Recovery policy updated',`Threshold ${threshold}; canary ${canary}%; cooldown ${cooldown}m`);render();toast('Policy saved')};
if($('dataset-form'))$('dataset-form').onsubmit=async e=>{e.preventDefault();$('data-error').textContent='';try{const file=$('dataset-file').files[0];if(!file||file.size>2*1024*1024)throw Error('Choose a CSV file smaller than 2 MB.');const name=$('dataset-name').value.trim();if(!name)throw Error('Enter a dataset name.');const rows=parseCSV((await file.text()).replace(/^\uFEFF/,''));if(rows.length<2)throw Error('CSV must contain headers and at least one data row.');const headers=rows.shift().map(x=>x.trim().toLowerCase());if(new Set(headers).size!==headers.length)throw Error('CSV headers must be unique.');const ui=headers.indexOf('url'),li=headers.indexOf('label');if(ui<0||li<0)throw Error('Required columns: url,label.');let errors=0,malicious=0;const seen=new Set(),issues=[];rows.forEach((r,i)=>{const url=(r[ui]||'').trim(),label=(r[li]||'').trim();let message='';try{scoreURL(url)}catch{message='Invalid URL'}if(!['0','1'].includes(label))message+=' Invalid label';if(seen.has(url))message+=' Duplicate URL';if(r.length!==headers.length)message+=' Column count mismatch';seen.add(url);if(label==='1')malicious++;if(message){errors++;if(issues.length<8)issues.push(`Row ${i+2}: ${message.trim()}`)}});const d={name,rows:rows.length,malicious,errors,time:new Date().toISOString()};state.datasets.unshift(d);state.datasets=state.datasets.slice(0,100);event('Dataset validated',`${name}: ${rows.length} rows; ${errors} invalid rows`,errors?'warning':'info');if(page==='data'){render();$('data-result').innerHTML=`<div class="result">${pill(errors?'Rejected':'Passed',errors?'red':'')}<h3>${rows.length} rows validated</h3><p>${errors} invalid rows · ${malicious} labeled malicious</p>${issues.length?'<ul>'+issues.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>':''}</div>`}}catch(err){if($('data-error'))$('data-error').textContent=err.message}}}
$('close-dialog').onclick=()=>$('dialog').close();$('about-demo').onclick=()=>showDialog('A functional demonstration workspace','<p>This release exercises the platform UI and recovery state transitions. It uses browser-local storage, deterministic scenario metrics, and a transparent lexical URL scorer. It does not train models, measure real drift, or deploy infrastructure. No submitted URL is fetched. The production backend is the next implementation milestone.</p>');window.addEventListener('hashchange',()=>{filter='';render();window.scrollTo(0,0)});function tick(){$('clock').textContent=new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}tick();setInterval(tick,30000);render();

